 *
 * Licensed under the Apache License version 2.0, available at http://www.apache.org/licenses/LICENSE-2.0
 */
package org.mapstruct.ap.test.inheritsupermappings;

import org.mapstruct.ap.testutil.ProcessorTest;
import org.mapstruct.ap.testutil.WithClasses;
import org.mapstruct.ap.testutil.compilation.annotation.CompilationResult;
import org.mapstruct.ap.testutil.compilation.annotation.Diagnostic;
import org.mapstruct.ap.testutil.compilation.annotation.ExpectedCompilationOutcome;

import static org.assertj.core.api.Assertions.assertThat;

public class InheritedSuperMappingsTest {

    @ProcessorTest
    @WithClasses(InheritedSuperMappingsMapper.class)
    public void shouldInheritMappingsFromOverriddenMethods() {
        Source left = new Source();
        left.setValue( "left" );
        left.setAutoValue( "automatic" );
        Source right = new Source();
        right.setValue( "right" );
        right.setFlatValue( "flat" );

        TargetBean target = InheritedSuperMappingsMapper.INSTANCE.map( left, right );

        assertThat( target.getBaseValue() ).isEqualTo( "left" );
        assertThat( target.getMiddleValue() ).isEqualTo( "left" );
        assertThat( target.getCurrentValue() ).isEqualTo( "right" );
        assertThat( target.getComposedValue() ).isEqualTo( "right" );
        assertThat( target.getExpressionValue() ).isEqualTo( "expression" );
        assertThat( target.getFlatValue() ).isEqualTo( "flat" );
        assertThat( target.getAutoValue() ).isEqualTo( "automatic" );
    }

    @ProcessorTest
    @WithClasses(ConflictingSuperMappingsMapper.class)
    @ExpectedCompilationOutcome(
        value = CompilationResult.FAILED,
        diagnostics = @Diagnostic(
            type = ConflictingSuperMappingsMapper.class,
            kind = javax.tools.Diagnostic.Kind.ERROR,
            line = 17,
            message = "Inherited mappings for target \"baseValue\" conflict between mapper types "
                + "org.mapstruct.ap.test.inheritsupermappings.LeftMapping and "
                + "org.mapstruct.ap.test.inheritsupermappings.RightMapping."
        )
    )
    public void shouldReportConflictingBranches() {
    }

    @ProcessorTest
    @WithClasses(NoSuperMappingMapper.class)
    @ExpectedCompilationOutcome(
        value = CompilationResult.FAILED,
        diagnostics = @Diagnostic(
            type = NoSuperMappingMapper.class,
            kind = javax.tools.Diagnostic.Kind.ERROR,
            line = 15,
            message = "@BeanMapping(inheritSuperMappings = true) requires an overridden mapping method."
        )
    )
    public void shouldRequireOverriddenMappingMethod() {
    }
}
